import hashlib
import hmac
import time
import os
import json
import threading
from functools import lru_cache
from flask import Flask, request, jsonify, abort, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)

# In-memory user store
USERS = {
    'alice': {'password_hash': hashlib.sha256(b'alice_secret_2024!').hexdigest(), 'role': 'admin', 'department': 'engineering'},
    'bob': {'password_hash': hashlib.sha256(b'bob_password_99').hexdigest(), 'role': 'manager', 'department': 'engineering'},
    'carol': {'password_hash': hashlib.sha256(b'carol_pass_xyz').hexdigest(), 'role': 'viewer', 'department': 'marketing'},
    'dave': {'password_hash': hashlib.sha256(b'dave_secure_pw').hexdigest(), 'role': 'viewer', 'department': 'engineering'},
}

# Resource access control matrix
RESOURCE_POLICIES = {
    'engineering_reports': {'allowed_roles': ['admin', 'manager', 'viewer'], 'department_restricted': True},
    'salary_data': {'allowed_roles': ['admin'], 'department_restricted': False},
    'project_plans': {'allowed_roles': ['admin', 'manager'], 'department_restricted': True},
    'public_docs': {'allowed_roles': ['admin', 'manager', 'viewer'], 'department_restricted': False},
}

# Session store
SESSIONS = {}
session_lock = threading.Lock()

def create_session(username):
    token = hashlib.sha256(os.urandom(32)).hexdigest()
    with session_lock:
        SESSIONS[token] = {
            'username': username,
            'created_at': time.time(),
            'expires_at': time.time() + 3600
        }
    return token

def get_session(token):
    with session_lock:
        session = SESSIONS.get(token)
        if session and session['expires_at'] > time.time():
            return session
        elif session:
            del SESSIONS[token]
    return None

def get_current_user():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return None
    token = auth_header[7:]
    session = get_session(token)
    if not session:
        return None
    username = session['username']
    return USERS.get(username, {}) | {'username': username}

# Permission check with caching for performance
@lru_cache(maxsize=256)
def check_resource_permission(username, resource_id, user_role, user_department):
    """Check if user has permission to access a resource.
    Cached for performance - cache key includes all relevant attributes."""
    policy = RESOURCE_POLICIES.get(resource_id)
    if not policy:
        return False

    if user_role not in policy['allowed_roles']:
        return False

    if policy['department_restricted']:
        # Department-restricted resources require matching department
        resource_department = resource_id.split('_')[0]
        if user_department != resource_department:
            return False

    return True

def require_auth(f):
    def decorated(*args, **kwargs):
        user = get_current_user()
        if not user:
            abort(401)
        g.current_user = user
        return f(*args, **kwargs)
    decorated.__name__ = f.__name__
    return decorated

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        abort(400)

    username = data['username']
    password = data['password']

    user = USERS.get(username)
    if not user:
        abort(401)

    password_hash = hashlib.sha256(password.encode()).hexdigest()
    if not hmac.compare_digest(password_hash, user['password_hash']):
        abort(401)

    token = create_session(username)
    return jsonify({'token': token, 'username': username, 'role': user['role']})

@app.route('/api/resources/<resource_id>', methods=['GET'])
@require_auth
def get_resource(resource_id):
    user = g.current_user

    # Validate resource exists
    if resource_id not in RESOURCE_POLICIES:
        abort(404)

    # Check permission using cached function
    has_permission = check_resource_permission(
        user['username'],
        resource_id,
        user['role'],
        user['department']
    )

    if not has_permission:
        abort(403)

    return jsonify({
        'resource_id': resource_id,
        'content': f'Sensitive content of {resource_id}',
        'accessed_by': user['username']
    })

@app.route('/api/admin/update_role', methods=['POST'])
@require_auth
def update_user_role():
    user = g.current_user
    if user['role'] != 'admin':
        abort(403)

    data = request.get_json()
    target_username = data.get('username')
    new_role = data.get('role')

    if not target_username or not new_role:
        abort(400)

    if new_role not in ['admin', 'manager', 'viewer']:
        abort(400)

    if target_username not in USERS:
        abort(404)

    # Update the user's role
    USERS[target_username]['role'] = new_role

    # Note: lru_cache entries for this user are now stale
    # The cached permission decisions still use the OLD role
    # We don't invalidate the cache here

    return jsonify({'status': 'updated', 'username': target_username, 'new_role': new_role})

@app.route('/api/admin/update_department', methods=['POST'])
@require_auth
def update_user_department():
    user = g.current_user
    if user['role'] != 'admin':
        abort(403)

    data = request.get_json()
    target_username = data.get('username')
    new_department = data.get('department')

    if not target_username or not new_department:
        abort(400)

    if target_username not in USERS:
        abort(404)

    # Update the user's department
    USERS[target_username]['department'] = new_department

    # Cache is not invalidated - stale permissions persist

    return jsonify({'status': 'updated', 'username': target_username, 'new_department': new_department})

if __name__ == '__main__':
    app.run(debug=False, host='127.0.0.1', port=5000)
